  {"week_number": 7, "focus": "Consolidation", "sessions": [{"day": 1, "workout_name": "Aerobic Long Swim 3000m", "description": "Swim", "duration_minutes": 70, "intensity": "easy"},{"day": 2, "workout_name": "Aerobic Run with Pickups (55 min)", "description": "Run", "duration_minutes": 55, "intensity": "moderate"},{"day": 3, "workout_name": "Aerobic + Threshold Long Combo (70 min)", "description": "Bike", "duration_minutes": 70, "intensity": "moderate"},{"day": 4, "workout_name": "Aerobic Volume 6x400 m with Rest", "description": "Swim", "duration_minutes": 65, "intensity": "easy"},{"day": 6, "workout_name": "Aerobic Volume Ride (120 min)", "description": "Long bike", "duration_minutes": 120, "intensity": "moderate"}]},
